    for i in range(len(ab)):
        for j in range(len(ab)):
            if i==j: continue
            (r1,c1),(r2,c2)=ab[i],ab[j]
            if r2>r1 and (r2-r1==c1-c2 or r2==r1+1):  # anti-diag or adjacent-row pair
                out[r2][c1]=4
